$:node <<'NODE'
"use strict";
const assert=require("node:assert/strict");
const {execFileSync}=require("node:child_process");
const api="repos/BestNameYet/Terminals/issues/3";
function gh(args){return JSON.parse(execFileSync("gh",["api",...args],{encoding:"utf8",maxBuffer:8*1024*1024}));}
const issue=gh([api]);
const d=JSON.parse(issue.body);
assert.equal(d.schema,"terminals.issue3.comment-terminal.instructions.v1");
assert.equal(d.issue,3);
assert.equal(d.repository,"BestNameYet/Terminals");
d.permissions.actions="write";
d.capabilities=d.capabilities||{};
d.capabilities.shared_conversation_extraction={
  schema:"terminals.issue3.shared-conversation-extraction.v1",
  name:"Extract and publish a public ChatGPT shared conversation",
  entrypoint_workflow:".github/workflows/chatgpt-shared-conversation-extractor.yml",
  trigger:"workflow_dispatch",
  invoked_through_issue_3:{
    runOn:"$",
    whatPrompt_template:"gh workflow run chatgpt-shared-conversation-extractor.yml --repo BestNameYet/Terminals --ref main --raw-field request_json='<SERIALIZED_JSON_REQUEST>'",
    requires_permissions:{actions:"write",contents:"write",issues:"write"},
    authorization:"Only the repository owner can submit an executable Issue #3 command."
  },
  request:{
    transport:"Workflow input request_json containing a JSON object serialized as a string",
    properties:{
      target_url:{type:"string",required:true,description:"Absolute HTTPS URL https://chatgpt.com/share/<share_uuid>"},
      write_path:{type:"string",required:false,default:"workspaces/shared-conversations/{share_uuid}/{run_id}-{run_attempt}",description:"Run-isolated destination template within the approved shared-conversations root"},
      request_id:{type:"string",required:false,description:"Caller-defined correlation ID; generated from run ID and attempt if omitted"},
      export_profile:{type:"string",required:false,default:"complete",enum:["complete"]}
    },
    allow_unknown_properties:false,
    modes:"request_json and legacy target_url/write_path dispatch inputs are mutually exclusive",
    legacy_inputs:["target_url","write_path"]
  },
  extraction:{
    acquisition:"One HTTP HTML capture",
    decoder:"Nonexecuting React Router indexed-stream parser",
    methods:[
      {id:"source-linear-v1",source:"linear_conversation",output:"linear-conversation.json",meaning:"Source-order complete structured node projection"},
      {id:"selected-parent-chain-v1",source:"mapping and current_node parent ancestry",outputs:["conversation.json","conversation.md"],meaning:"Selected-branch visible text projection"}
    ]
  },
  publication:{
    destination_template:"workspaces/shared-conversations/{share_uuid}/{run_id}-{run_attempt}",
    repository:"BestNameYet/Terminals",
    branch:"main",
    required_files:["response.html","conversation-raw.json","linear-conversation.json","conversation.json","conversation.md","diagnostics.json","receipt.json","execution.json"],
    github_actions_artifacts:[
      "chatgpt-shared-export-{run_id}-{run_attempt}",
      "chatgpt-shared-export-final-attestation-{run_id}-{run_attempt}"
    ],
    artifact_retention_days:30,
    success_criteria:[
      "The target extractor workflow run is identified and its conclusion is success",
      "All eight required files are present under the resolved destination",
      "Receipt digests and file sizes match generated bytes",
      "Every published file is independently read back from origin/main and compared byte-for-byte",
      "A separate final publication attestation states VERIFIED and names the published commit SHA"
    ],
    status_rule:"Successful command submission or dispatch acceptance alone is not evidence of successful extraction or publication."
  },
  test_commands:[
    "node --test workspaces/extractor-srs-design/tests/*.test.js",
    "node --test --test-concurrency=4 workspaces/extractor-srs-design/tests/*.test.js workspaces/extractor-srs-design/input-validator.test.js"
  ],
  verified_example:{
    workflow_run_id:41645489733,
    workflow_run_url:"https://github.com/BestNameYet/Terminals/actions/runs/41645489733",
    result:"success",
    publication_commit:"e4a2aac59c7100fb3eae5f20f9c4b89ec0a655b9",
    output_directory:"workspaces/shared-conversations/6ae9dd85-7ff0-83e8-90c3-4592305a2362/41645489733-1",
    verified_file_count:8,
    source_linear_nodes:5912,
    selected_visible_messages:592,
    regression_test_count:149
  }
};
const example={
  runOn:"$",
  whatPrompt:"gh workflow run chatgpt-shared-conversation-extractor.yml --repo BestNameYet/Terminals --ref main --raw-field request_json='{\"target_url\":\"https://chatgpt.com/share/6ae9dd85-7ff0-83e8-90c3-4592305a2362\",\"export_profile\":\"complete\"}'",
  forWhom:"GPT6_0000000061-extract_shared_conversation-Terminals"
};
if(!d.input.examples.some(e=>e.forWhom===example.forWhom))d.input.examples.push(example);
const body=JSON.stringify(d,null,2)+"\n";
if(issue.body!==body){
  gh(["--method","PATCH",api,"-f","body="+body]);
}
const verified=gh([api]);
assert.deepEqual(JSON.parse(verified.body),d);
console.log(JSON.stringify({updated:issue.body!==body,issue:3,schema:d.schema,capability:d.capabilities.shared_conversation_extraction.schema,permissions:d.permissions,example_count:d.input.examples.length,output_count:d.capabilities.shared_conversation_extraction.publication.required_files.length,body_chars:verified.body.length,readback_verified:true,url:verified.html_url}));
NODE
